import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const n="/assets/image_1.r9POWnvR.png",l="/assets/image_2.BLI6TqA3.png",s="/assets/image_3.CMk6ri_o.png",r="/assets/image_4.yxWHcxCt.png",c="data:image/png;base64,",h="/assets/image_6.Xk_7Rtxp.png",u="data:image/png;base64,",d="/assets/image_8.CPNDo1Ec.png",p="/assets/image_9.DZJ_En_L.png",A="data:image/png;base64,",g="/assets/image_11.DVu13oVq.png",m="/assets/image_12.YBaNTx8B.png",b="/assets/image_13.CPV7Pc7D.png",q="/assets/image_14.DNMu3pE9.png",f="/assets/image_15.5d4oXvZk.png",C="/assets/image_16.DEWHfNx8.png",E="/assets/image_17.CcnY4UB_.png",I="/assets/image_18.8WTRwWiE.png",P="/assets/image_19.COOhneoK.png",B="/assets/image_20.CWSSYbJP.png",v="/assets/image_21.C5nv8Mog.png",x="/assets/image_22.Bh_EjxUG.png",w="/assets/image_23.BjEsOsUG.png",R="/assets/image_24.7fNrMWhY.png",S="/assets/image_25.C-08Cwh0.png",Q="/assets/image_26.DhV9A_xB.png",F=JSON.parse('{"title":"Advanced Outline System","description":"","frontmatter":{},"headers":[],"relativePath":"unreal/advanced-outline-system/index.md","filePath":"unreal/advanced-outline-system/index.md"}'),V={name:"unreal/advanced-outline-system/index.md"};function j(O,e,k,U,D,H){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="advanced-outline-system" tabindex="-1"><strong>Advanced Outline System</strong> <a class="header-anchor" href="#advanced-outline-system" aria-label="Permalink to &quot;**Advanced Outline System**&quot;">​</a></h1><h1 id="_1-introduction" tabindex="-1"><strong>1. Introduction</strong> <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;**1\\. Introduction**&quot;">​</a></h1><p>The Advanced Outline System is a flexible and runtime-adjustable outline framework for Unreal Engine. It allows you to apply customizable outlines to actors and components using stencil-based color mapping.</p><p>The system supports:</p><ul><li><p>Global outline control</p></li><li><p>Multiple stencil-based colors</p></li><li><p>Runtime thickness and opacity control</p></li><li><p>View mode switching (hide behind objects or visible through objects)</p></li><li><p>Blueprint integration</p></li><li><p>For detailed descriptions of all available functions, refer to the included reference actor located in <strong>Plugins → AdvancedOutlineSystem → Content → Demo → BP_InfoActor</strong> (enable <strong>Show Plugin Content</strong> if it is not visible). <img src="'+n+'" alt=""></p></li></ul><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="-2" tabindex="-1"><a class="header-anchor" href="#-2" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="_2-installation" tabindex="-1"><strong>2. Installation</strong> <a class="header-anchor" href="#_2-installation" aria-label="Permalink to &quot;**2\\. Installation**&quot;">​</a></h1><ol><li><p>Add the plugin to your project.</p></li><li><p>Enable the plugin in <strong>Edit → Plugins</strong>.</p></li><li><p>Restart the editor. <img src="'+l+'" alt=""></p></li></ol><h1 id="_3-required-setup" tabindex="-1"><strong>3. Required Setup</strong> <a class="header-anchor" href="#_3-required-setup" aria-label="Permalink to &quot;**3\\. Required Setup**&quot;">​</a></h1><h2 id="_3-1-enable-custom-depth-with-stencil" tabindex="-1"><strong>3.1 Enable Custom Depth with Stencil</strong> <a class="header-anchor" href="#_3-1-enable-custom-depth-with-stencil" aria-label="Permalink to &quot;**3.1 Enable Custom Depth with Stencil**&quot;">​</a></h2><p>The Advanced Outline System relies on Unreal Engine’s Custom Depth Stencil buffer.</p><p>Before using the system, you must enable stencil support:</p><ol><li>Open **Edit → Project Settings **</li><li>Navigate to **Rendering → Post Processing **</li><li>Search for **Custom Depth-Stencil Pass **</li><li>Set it to : <strong>Enabled with Stencil <img src="'+s+'" alt=""></strong></li></ol><p>This step is mandatory. If this option is not enabled, outlines will not render correctly.</p><h1 id="_4-project-settings-configuration" tabindex="-1"><strong>4. Project Settings Configuration</strong> <a class="header-anchor" href="#_4-project-settings-configuration" aria-label="Permalink to &quot;**4\\. Project Settings Configuration**&quot;">​</a></h1><p>Go to:</p><p><strong>Edit → Project Settings → Plugins → AdvancedOutline</strong><img src="'+r+'" alt=""></p><p>You will find the following options:</p><h2 id="_4-1-default-thickness" tabindex="-1"><strong>4.1 Default Thickness</strong> <a class="header-anchor" href="#_4-1-default-thickness" aria-label="Permalink to &quot;**4.1 Default Thickness**&quot;">​</a></h2><p>Controls the default outline thickness for all objects.</p><p>Range: 1 to 5 <img src="'+c+'" alt=""></p><h2 id="-3" tabindex="-1"><a class="header-anchor" href="#-3" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-4" tabindex="-1"><a class="header-anchor" href="#-4" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="_4-2-default-outline-view-mode" tabindex="-1"><strong>4.2 Default Outline View Mode</strong> <a class="header-anchor" href="#_4-2-default-outline-view-mode" aria-label="Permalink to &quot;**4.2 Default Outline View Mode**&quot;">​</a></h2><p>Defines how outlines are rendered:</p><ul><li><p>Hide Behind Objects – Outline is hidden if blocked by other objects.</p></li><li><p>Visible Through Objects – Outline remains visible even if blocked by other objects.</p></li></ul><p><img src="'+h+'" alt=""></p><h2 id="_4-3-default-outline-color" tabindex="-1"><strong>4.3 Default Outline Color</strong> <a class="header-anchor" href="#_4-3-default-outline-color" aria-label="Permalink to &quot;**4.3 Default Outline Color**&quot;">​</a></h2><p>Fallback color used when stencil value is 0.<img src="'+u+'" alt=""></p><h2 id="_4-4-stencil-color-container" tabindex="-1"><strong>4.4 Stencil Color Container</strong> <a class="header-anchor" href="#_4-4-stencil-color-container" aria-label="Permalink to &quot;**4.4 Stencil Color Container**&quot;">​</a></h2><p>Maps stencil values to specific outline colors.</p><p>Important:</p><ul><li><p>Stencil 0 → Uses Default Outline Color.</p></li><li><p>Stencil 253 and 254 → Reserved.</p></li><li><p>Stencil 255 → Renders above all outlined objects. You can assign different colors to different stencil indices to create categorized outline colors (e.g interactable, enemy, objective).</p></li></ul><p><img src="'+d+'" alt=""></p><h2 id="-5" tabindex="-1"><a class="header-anchor" href="#-5" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="_4-5-components-to-exclude" tabindex="-1"><strong>4.5 Components To Exclude</strong> <a class="header-anchor" href="#_4-5-components-to-exclude" aria-label="Permalink to &quot;**4.5 Components To Exclude**&quot;">​</a></h2><p>Defines component classes that should not receive outlines when using actor level functions.</p><p>Useful for:</p><ul><li><p>Collision components</p></li><li><p>Gizmos</p></li><li><p>Helper components</p></li><li><p>Text render components</p></li></ul><p><img src="'+p+'" alt=""></p><h1 id="-6" tabindex="-1"><a class="header-anchor" href="#-6" aria-label="Permalink to &quot;&quot;">​</a></h1><h2 id="_4-6-vr-platform-check" tabindex="-1"><strong>4.6 VR Platform Check</strong> <a class="header-anchor" href="#_4-6-vr-platform-check" aria-label="Permalink to &quot;**4.6 VR Platform Check**&quot;">​</a></h2><p>This setting determines whether the outline system is being used in a VR project. When enabled, the system applies VR-specific configurations to ensure proper rendering and behavior on VR platforms. This helps avoid visual issues and ensures compatibility with VR environments.</p><p>Set this value to <strong>true</strong> when using the system in a VR project, and <strong>false</strong> for non-VR platforms</p><p><img src="'+A+'" alt=""></p><h1 id="_5-usage" tabindex="-1"><strong>5. Usage</strong> <a class="header-anchor" href="#_5-usage" aria-label="Permalink to &quot;**5\\. Usage**&quot;">​</a></h1><p>All runtime functionality is accessible via Blueprint and c++.</p><p>The system is managed by the <strong>AdvancedOutlineSubsystem</strong>.</p><p>To access it: Use GetAdvancedOutlineSubsystem. <img src="'+g+'" alt=""></p><p><img src="'+m+'" alt=""></p><h1 id="-7" tabindex="-1"><strong><img src="'+b+'" alt=""></strong> <a class="header-anchor" href="#-7" aria-label="Permalink to &quot;**![](./assets/image_13.png)**&quot;">​</a></h1><h1 id="_6-showing-and-hiding-outlines" tabindex="-1"><strong>6. Showing and Hiding Outlines</strong> <a class="header-anchor" href="#_6-showing-and-hiding-outlines" aria-label="Permalink to &quot;**6\\. Showing and Hiding Outlines**&quot;">​</a></h1><h2 id="_6-1-show-outline-on-actor" tabindex="-1"><strong>6.1 Show Outline on Actor</strong> <a class="header-anchor" href="#_6-1-show-outline-on-actor" aria-label="Permalink to &quot;**6.1 Show Outline on Actor**&quot;">​</a></h2><p>Use:</p><ul><li>ShowActorOutline(Actor, true)</li></ul><p>To remove outline:</p><ul><li>ShowActorOutline(Actor, false)</li></ul><p>This applies the outline to all eligible components of the actor.</p><p><img src="'+q+'" alt=""></p><h2 id="_6-2-show-outline-on-component" tabindex="-1"><strong>6.2 Show Outline on Component</strong> <a class="header-anchor" href="#_6-2-show-outline-on-component" aria-label="Permalink to &quot;**6.2 Show Outline on Component**&quot;">​</a></h2><p>Use:</p><ul><li>ShowComponentOutline(Component, true)</li></ul><p>This affects only the selected component.</p><p><img src="'+f+'" alt=""></p><h1 id="-8" tabindex="-1"><a class="header-anchor" href="#-8" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="-9" tabindex="-1"><a class="header-anchor" href="#-9" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="-10" tabindex="-1"><a class="header-anchor" href="#-10" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="-11" tabindex="-1"><a class="header-anchor" href="#-11" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="_7-changing-outline-colors" tabindex="-1"><strong>7. Changing Outline Colors</strong> <a class="header-anchor" href="#_7-changing-outline-colors" aria-label="Permalink to &quot;**7\\. Changing Outline Colors**&quot;">​</a></h1><p>The system uses Custom Depth Stencil values to determine outline color.</p><h2 id="_7-1-set-actor-stencil-value" tabindex="-1"><strong>7.1 Set Actor Stencil Value</strong> <a class="header-anchor" href="#_7-1-set-actor-stencil-value" aria-label="Permalink to &quot;**7.1 Set Actor Stencil Value**&quot;">​</a></h2><ul><li>SetActorCustomDepthStencilValue(Actor, StencilValue)</li></ul><p>Example:</p><ul><li><p>Stencil 1 → Red</p></li><li><p>Stencil 2 → Green</p></li><li><p>Stencil 3 → Blue</p></li></ul><p>Make sure the stencil value is configured inside the Stencil Color Container. <img src="'+C+'" alt=""></p><h2 id="-12" tabindex="-1"><a class="header-anchor" href="#-12" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="_7-2-set-component-stencil-value" tabindex="-1"><strong>7.2 Set Component Stencil Value</strong> <a class="header-anchor" href="#_7-2-set-component-stencil-value" aria-label="Permalink to &quot;**7.2 Set Component Stencil Value**&quot;">​</a></h2><ul><li>SetComponentCustomDepthStencilValue(Component, StencilValue)</li></ul><p><img src="'+E+'" alt=""></p><h1 id="_8-global-controls" tabindex="-1"><strong>8. Global Controls</strong> <a class="header-anchor" href="#_8-global-controls" aria-label="Permalink to &quot;**8\\. Global Controls**&quot;">​</a></h1><h2 id="_8-1-change-outline-thickness" tabindex="-1"><strong>8.1 Change Outline Thickness</strong> <a class="header-anchor" href="#_8-1-change-outline-thickness" aria-label="Permalink to &quot;**8.1 Change Outline Thickness**&quot;">​</a></h2><ul><li>SetOutlineThickness(Thickness)</li></ul><p>Affects all outlined objects.</p><p><img src="'+I+'" alt=""></p><h2 id="_8-2-change-outline-opacity" tabindex="-1"><strong>8.2 Change Outline Opacity</strong> <a class="header-anchor" href="#_8-2-change-outline-opacity" aria-label="Permalink to &quot;**8.2 Change Outline Opacity**&quot;">​</a></h2><ul><li>SetOutlineOpacity(Opacity)</li></ul><p>Controls transparency of all outlines.</p><p><img src="'+P+'" alt=""></p><h2 id="-13" tabindex="-1"><a class="header-anchor" href="#-13" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-14" tabindex="-1"><a class="header-anchor" href="#-14" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-15" tabindex="-1"><a class="header-anchor" href="#-15" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-16" tabindex="-1"><a class="header-anchor" href="#-16" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="_8-3-change-global-outline-color" tabindex="-1"><strong>8.3 Change Global Outline Color</strong> <a class="header-anchor" href="#_8-3-change-global-outline-color" aria-label="Permalink to &quot;**8.3 Change Global Outline Color**&quot;">​</a></h2><ul><li>SetGlobalOutlineColor(Color)</li></ul><p>Affects all objects using stencil value 0.</p><p><img src="'+B+'" alt=""></p><h1 id="_9-outline-view-modes" tabindex="-1"><strong>9. Outline View Modes</strong> <a class="header-anchor" href="#_9-outline-view-modes" aria-label="Permalink to &quot;**9\\. Outline View Modes**&quot;">​</a></h1><p>You can control how outlines behave when objects are behind other geometry.</p><h2 id="_9-1-set-global-view-mode" tabindex="-1"><strong>9.1 Set Global View Mode</strong> <a class="header-anchor" href="#_9-1-set-global-view-mode" aria-label="Permalink to &quot;**9.1 Set Global View Mode**&quot;">​</a></h2><ul><li>SetOutlineViewMode(Mode)</li></ul><p>Affects all outlined objects unless overridden with specific actor/component view mode.</p><p><img src="'+v+'" alt=""></p><h2 id="-17" tabindex="-1"><a class="header-anchor" href="#-17" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-18" tabindex="-1"><a class="header-anchor" href="#-18" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="_9-2-override-view-mode-per-actor" tabindex="-1"><strong>9.2 Override View Mode Per Actor</strong> <a class="header-anchor" href="#_9-2-override-view-mode-per-actor" aria-label="Permalink to &quot;**9.2 Override View Mode Per Actor**&quot;">​</a></h2><ul><li>OverrideActorOutlineViewMode(Actor, Mode)</li></ul><p>Only affects that actor.</p><p><img src="'+x+'" alt=""></p><h2 id="_9-3-reset-actor-view-mode" tabindex="-1"><strong>9.3 Reset Actor View Mode</strong> <a class="header-anchor" href="#_9-3-reset-actor-view-mode" aria-label="Permalink to &quot;**9.3 Reset Actor View Mode**&quot;">​</a></h2><ul><li>ResetActorOutlineViewMode(Actor)</li></ul><p>Restores global behavior.</p><p><img src="'+w+'" alt=""></p><h2 id="-19" tabindex="-1"><a class="header-anchor" href="#-19" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-20" tabindex="-1"><a class="header-anchor" href="#-20" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-21" tabindex="-1"><a class="header-anchor" href="#-21" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="-22" tabindex="-1"><a class="header-anchor" href="#-22" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="_9-4-override-view-mode-per-component" tabindex="-1"><strong>9.4 Override View Mode Per Component</strong> <a class="header-anchor" href="#_9-4-override-view-mode-per-component" aria-label="Permalink to &quot;**9.4 Override View Mode Per Component**&quot;">​</a></h2><ul><li>OverrideComponentOutlineViewMode(Component, Mode)</li></ul><p>Only affects that component.</p><p><img src="'+R+'" alt=""></p><h2 id="_9-5-reset-component-view-mode" tabindex="-1"><strong>9.5 Reset Component View Mode</strong> <a class="header-anchor" href="#_9-5-reset-component-view-mode" aria-label="Permalink to &quot;**9.5 Reset Component View Mode**&quot;">​</a></h2><ul><li>ResetComponentOutlineViewMode(Component)</li></ul><p>Restores global behavior.</p><p><img src="'+S+'" alt=""></p><h1 id="-23" tabindex="-1"><a class="header-anchor" href="#-23" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="-24" tabindex="-1"><a class="header-anchor" href="#-24" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="-25" tabindex="-1"><a class="header-anchor" href="#-25" aria-label="Permalink to &quot;&quot;">​</a></h1><h1 id="_10-understanding-stencil-values" tabindex="-1"><strong>10. Understanding Stencil Values</strong> <a class="header-anchor" href="#_10-understanding-stencil-values" aria-label="Permalink to &quot;**10\\. Understanding Stencil Values**&quot;">​</a></h1><p>Stencil values control color and rendering behavior.</p><p>Reserved Values:</p><ul><li><p>0 → Global color</p></li><li><p>253 and 254 → Reserved</p></li><li><p>255 → Highest priority render</p></li></ul><p>Use values between 1 and 252 for custom colors.</p><h1 id="_11-typical-use-cases" tabindex="-1"><strong>11. Typical Use Cases</strong> <a class="header-anchor" href="#_11-typical-use-cases" aria-label="Permalink to &quot;**11\\. Typical Use Cases**&quot;">​</a></h1><h3 id="interactable-objects" tabindex="-1"><strong>Interactable Objects</strong> <a class="header-anchor" href="#interactable-objects" aria-label="Permalink to &quot;**Interactable Objects**&quot;">​</a></h3><ul><li>Assign stencil 1 (yellow outline).</li></ul><h3 id="enemies" tabindex="-1"><strong>Enemies</strong> <a class="header-anchor" href="#enemies" aria-label="Permalink to &quot;**Enemies**&quot;">​</a></h3><ul><li>Assign stencil 2 (red outline).</li></ul><h3 id="objectives" tabindex="-1"><strong>Objectives</strong> <a class="header-anchor" href="#objectives" aria-label="Permalink to &quot;**Objectives**&quot;">​</a></h3><ul><li>Assign stencil 3 (blue outline).</li></ul><p><img src="'+Q+'" alt=""></p>',142)])])}const G=t(V,[["render",j]]);export{F as __pageData,G as default};
